"""bitmart_futures.pyBitMart USDT-M Futures Perpetual bot — connectivity scaffold.This is step 1 of the pivot away from the CEX-arbitrage bot (analyzer.py /trader.py) toward a dedicated BitMart Futures scalping bot, per the newproject brief. Per explicit instruction, this step ONLY implements:  - Loading BitMart credentials from the `api_keys` Supabase table, using    the GENERAL (non-restricted) columns — not the restricted ones.  - Connecting to BitMart's Futures V2 public WebSocket and subscribing to    one channel as a live connectivity check.  - Connecting to BitMart's Futures V2 private WebSocket and logging in    with those credentials.  - Automatic reconnect with backoff on either socket, plus the app-level    ping BitMart's WS requires to stay alive.None of the order-flow analysis, entry/exit logic, position management,execution, risk management, logging/stats/visualization, or the eventualremoval of the old arbitrage code from analyzer.py/trader.py is implementedhere yet — that all builds on top of this once connectivity is confirmedworking end-to-end. analyzer.py and trader.py are untouched by this file.Docs referenced (BitMart Futures V2 WebSocket Subscription section):  https://developer-pro.bitmart.com/en/futuresv2/"""import asyncioimport hashlibimport hmacimport jsonimport loggingimport osimport timeimport websocketslogging.basicConfig(    level=logging.INFO,    format="%(asctime)s  %(message)s",    handlers=[logging.FileHandler("bitmart_futures.log"), logging.StreamHandler()],)log = logging.getLogger()# ----------------------------------------------------------------------#  Config# ----------------------------------------------------------------------# Flip to False once you're ready to point this at the live BitMart account.DEMO_TRADING = TruePROD_PUBLIC_WS = "wss://openapi-ws-v2.bitmart.com/api?protocol=1.1"PROD_PRIVATE_WS = "wss://openapi-ws-v2.bitmart.com/user?protocol=1.1"DEMO_PUBLIC_WS = "wss://openapi-wsdemo-v2.bitmart.com/api?protocol=1.1"DEMO_PRIVATE_WS = "wss://openapi-wsdemo-v2.bitmart.com/user?protocol=1.1"PUBLIC_WS_URL = DEMO_PUBLIC_WS if DEMO_TRADING else PROD_PUBLIC_WSPRIVATE_WS_URL = DEMO_PRIVATE_WS if DEMO_TRADING else PROD_PRIVATE_WS# BitMart force-closes a connection that goes >20s with no traffic at all,# and treats a connection as "lifeless" (and closes it) if it doesn't see a# subscription within 5s of opening. We ping well inside the 20s window.PING_INTERVAL_SEC = 15RECONNECT_BASE_DELAY_SEC = 3RECONNECT_MAX_DELAY_SEC = 60# A cheap, always-active public channel used purely to prove the public# socket is alive and receiving pushes — not a feed we act on yet.CONNECTIVITY_TEST_CHANNEL = "futures/ticker"# ----------------------------------------------------------------------#  Supabase credentials (general / non-restricted keys, per instruction)# ----------------------------------------------------------------------def _load_db_config() -> dict:    here = os.path.dirname(os.path.abspath(__file__))    candidates = [        os.path.join(here, "db.txt"),        os.path.join(os.path.dirname(here), "db.txt"),    ]    for path in candidates:        if os.path.exists(path):            config = {}            with open(path, "r") as f:                for line in f:                    line = line.strip()                    if not line or line.startswith("#"):                        continue                    if "=" in line:                        k, _, v = line.partition("=")                        config[k.strip()] = v.strip().strip('"')            return config    raise FileNotFoundError(f"db.txt not found in any of: {candidates}")def _clean_secret(value):    if value is None:        return None    if isinstance(value, str):        value = value.strip()        if value.upper() in ("", "NULL"):            return None    return valuedef load_bitmart_credentials() -> dict:    """    Loads BitMart credentials from the `api_keys` Supabase table — the same    table analyzer.py already reads.    Per instruction, this uses the GENERAL (non-restricted) columns:    api_key / api_secret — not api_key_restricted / api_secret_restricted.    BitMart's WS login needs three values: api_key, secret, and memo.    BitMart calls it "memo", but ccxt's unified credential slot for it is    `uid` (see ccxt/ccxt#23715 — BitMart's own memo field is mapped to    ccxt's `uid`), and that's the same convention analyzer.py's existing    Supabase schema already follows for other exchanges. So memo is read    from the `uid` column here, not `passphrase`.    """    from supabase import create_client    config = _load_db_config()    sb = create_client(config["SUPABASE_URL"], config["SUPABASE_KEY"])    rows = sb.table("api_keys").select("*").execute()    match = next(        (r for r in rows.data or [] if (r.get("exchange_name") or "").strip().lower() == "bitmart"),        None,    )    if not match:        raise RuntimeError("No 'BitMart' row found in the api_keys Supabase table")    api_key = _clean_secret(match.get("api_key"))    api_secret = _clean_secret(match.get("api_secret"))    memo = _clean_secret(match.get("uid"))    missing = [n for n, v in (("api_key", api_key), ("api_secret", api_secret), ("uid/memo", memo)) if not v]    if missing:        raise RuntimeError(f"BitMart credentials incomplete in Supabase — missing: {', '.join(missing)}")    return {"api_key": api_key, "api_secret": api_secret, "memo": memo}# ----------------------------------------------------------------------#  Login signature# ----------------------------------------------------------------------def build_login_sign(timestamp_ms: str, memo: str, api_secret: str) -> str:    """    BitMart Futures WS login signature (per BitMart docs):      sign = HMAC_SHA256(f"{timestamp}#{memo}#bitmart.WebSocket", api_secret)    """    payload = f"{timestamp_ms}#{memo}#bitmart.WebSocket"    return hmac.new(api_secret.encode(), payload.encode(), hashlib.sha256).hexdigest()# ----------------------------------------------------------------------#  Shared keepalive# ----------------------------------------------------------------------async def _keepalive(ws):    """    Sends BitMart's app-level {"action":"ping"} every PING_INTERVAL_SEC.    BitMart replies with the plain text 'pong' (handled in the recv loops).    """    while True:        await asyncio.sleep(PING_INTERVAL_SEC)        try:            await ws.send(json.dumps({"action": "ping"}))        except Exception:            return  # socket already closing; outer loop will reconnect# ----------------------------------------------------------------------#  Public WebSocket (market data) — connectivity check only for now# ----------------------------------------------------------------------async def run_public():    delay = RECONNECT_BASE_DELAY_SEC    while True:        try:            log.info(f"[public] connecting to {PUBLIC_WS_URL}")            async with websockets.connect(PUBLIC_WS_URL, ping_interval=None) as ws:                log.info("[public] connected")                delay = RECONNECT_BASE_DELAY_SEC  # reset backoff on success                await ws.send(json.dumps({"action": "subscribe", "args": [CONNECTIVITY_TEST_CHANNEL]}))                keepalive_task = asyncio.create_task(_keepalive(ws))                try:                    async for raw in ws:                        if raw == "pong":                            continue                        try:                            msg = json.loads(raw)                        except json.JSONDecodeError:                            log.warning(f"[public] non-JSON message: {raw[:200]}")                            continue                        if msg.get("action") == "subscribe":                            if msg.get("success"):                                log.info(f"[public] \u2705 subscribed to {msg.get('group')}")                            else:                                log.error(f"[public] \u274c subscribe failed: {msg}")                        elif "group" in msg:                            log.info(f"[public] data: {msg.get('group')} -> {json.dumps(msg.get('data'))[:200]}")                        else:                            log.info(f"[public] message: {msg}")                finally:                    keepalive_task.cancel()        except Exception as e:            log.error(f"[public] connection error: {type(e).__name__}: {str(e)[:200]} \u2014 reconnecting in {delay}s")            await asyncio.sleep(delay)            delay = min(delay * 2, RECONNECT_MAX_DELAY_SEC)# ----------------------------------------------------------------------#  Private WebSocket (login only for now)# ----------------------------------------------------------------------async def run_private(creds: dict):    delay = RECONNECT_BASE_DELAY_SEC    while True:        try:            log.info(f"[private] connecting to {PRIVATE_WS_URL}")            async with websockets.connect(PRIVATE_WS_URL, ping_interval=None) as ws:                log.info("[private] connected \u2014 logging in")                delay = RECONNECT_BASE_DELAY_SEC                timestamp_ms = str(int(time.time() * 1000))                sign = build_login_sign(timestamp_ms, creds["memo"], creds["api_secret"])                login_msg = {"action": "access", "args": [creds["api_key"], timestamp_ms, sign, "web"]}                await ws.send(json.dumps(login_msg))                keepalive_task = asyncio.create_task(_keepalive(ws))                try:                    async for raw in ws:                        if raw == "pong":                            continue                        try:                            msg = json.loads(raw)                        except json.JSONDecodeError:                            log.warning(f"[private] non-JSON message: {raw[:200]}")                            continue                        if msg.get("action") == "access":                            if msg.get("success"):                                log.info("[private] \u2705 login successful")                            else:                                log.error(f"[private] \u274c login failed: {msg}")                                # Bad credentials won't fix themselves on retry —                                # back off harder so we're not hammering BitMart.                                await asyncio.sleep(RECONNECT_MAX_DELAY_SEC)                        else:                            log.info(f"[private] message: {msg}")                finally:                    keepalive_task.cancel()        except Exception as e:            log.error(f"[private] connection error: {type(e).__name__}: {str(e)[:200]} \u2014 reconnecting in {delay}s")            await asyncio.sleep(delay)            delay = min(delay * 2, RECONNECT_MAX_DELAY_SEC)# ----------------------------------------------------------------------#  Entry point# ----------------------------------------------------------------------async def main():    creds = load_bitmart_credentials()    log.info(f"Starting BitMart Futures WS connectivity check (demo_trading={DEMO_TRADING})")    await asyncio.gather(        run_public(),        run_private(creds),    )if __name__ == "__main__":    try:        asyncio.run(main())    except KeyboardInterrupt:        log.info("bitmart_futures.py stopped.")